def build(inorder, postorder):
    idx = {v: i for i, v in enumerate(inorder)}
    def rec(il, ir, pl, pr):
        if il > ir: return None
        root = TreeNode(postorder[pr])
        m = idx[postorder[pr]]
        left_n = m - il
        root.left = rec(il, m-1, pl, pl+left_n-1)
        root.right = rec(m+1, ir, pl+left_n, pr-1)
        return root
    return rec(0, len(inorder)-1, 0, len(postorder)-1)
```

